Translate("ruRU", "shadowfang-keep", {
	title = "Крепость Темного Клыка",
	aliases = { "Темный Клык" },
	sections = {
		{
			title = "Обзор",
			text = [=[Крепость Темного Клыка стоит на темном холме на юге {link:silverpine-forest}Серебряного бора{/link}, над Деревней П{link:ogres}огр{/link}ебальных Костров. Некогда это была резиденция благородного барона {link:baron-silverlaine}Сильверлейн{/link}а. Теперь это логово архимага {link:archmage-arugal}Аругал{/link}а и воргенов, которых он зовет своими детьми. {link:humans}Люди{/link}-волки рыщут по ее залам, ворги воют в ее дворах, а мертвецы из домочадцев барона все еще ходят по комнатам, где были убиты.]=],
		},
		{
			title = "Истоки",
			text = [=[В {link:third-war}Третью войну{/link} волшебники ордена {link:kirin-tor}Кирин-Тор{/link} сражались с {link:scourge}Плетью{/link} на севере. Каждый павший волшебник вскоре восставал вновь, чтобы биться за врага, и Плеть только росла. {link:archmage-arugal}Аругал{/link} не пожелал с этим смириться. Вопреки совету собратьев он призвал существ из-за пределов мира, чтобы пополнить редеющие ряды {link:dalaran}Даларана{/link}. На его зов откликнулись {red:worgen}воргены{/red}. Ненасытные люди-волки растерзали нежить, а затем обратились против самих волшебников. Они осадили крепость барона, и та пала во тьму и запустение. Обезумев от вины, Аругал принял воргенов как собственных детей. Он удалился в павшую крепость и дал ей новое имя: Темный Клык.]=],
		},
		{
			title = "Наши дни",
			text = [=[{link:forsaken}Отрекшиеся{/link} не могут удержать {link:silverpine-forest}Серебряный бор{/link}, пока {link:archmage-arugal}Аругал{/link} жив, и они поклялись увидеть его мертвым. {link:high-executor-hadrec}Верховный исполнитель Хадрек{/link} послал в крепость двух стражей смерти, чтобы выведать ее тайны. Они не вернулись. {link:kirin-tor}Кирин-Тор{/link} тоже послал своего агента, и его постигла та же участь. Оба теперь ждут в темницах близ ворот. {link:keeper-bel-dugur}Хранитель Бел'дугур{/link} из {link:undercity}Подгород{/link}а желает получить книгу, что лежит где-то в крепости, — труд даларанского мага Ура, который изучал иные миры. В Гробнице мертвый архимаг теперь утверждает, что Аругал вовсе не создавал воргенов.]=],
		},
		{
			title = "В стенах крепости",
			text = [=[• {b}Темницы.{/b} Близ входа ворген {link:rethilgore}Ретилгор{/link} держит своих пленников под замком.
• {b}Двор.{/b} За запечатанной дверью лежит внутренний двор, где мертвые солдаты крепости и воргены архимага вместе несут стражу.
• {b}Покои домочадцев.{/b} {link:razorclaw-the-butcher}Острокогть Мясник{/link} трудится на кухнях. Призрак барона обитает в трапезной, а командир {link:commander-springvale}Спрингвейл{/link} со своими мертвыми офицерами держит зал совета.
• {b}Высоты.{/b} {link:odo-the-blindwatcher}Одо Слепой Страж{/link} несет дозор высоко на стенах. {link:wolf-master-nandos}Повелитель волков Нандос{/link} гоняет свою стаю по верхнему двору, а {link:fenrus-the-devourer}Фенрус Пожиратель{/link} стережет покои своего хозяина.
• {b}{link:the-harborage}Убежище{/link} архимага.{/b} На вершине крепости архимаг ждет среди своих слуг.]=],
		},
	},
})

Translate("ruRU", "archmage-arugal", {
	title = "Архимаг Аругал",
	subtitle = "Хозяин Крепости Темного Клыка",
	found = "Самые верхние залы Крепости Темного Клыка",
	hint = [=[Узнайте о нем в Гробнице или поднимитесь на вершину Крепости Темного Клыка.]=],
	allegiance = "Сыновья архимага · прежде Кирин-Тор",
	aliases = { "Аругал" },
	sections = {
		{
			title = "Обзор",
			text = [=[Аругал был архимагом ордена {link:kirin-tor}Кирин-Тор{/link} из {link:dalaran}Даларана{/link}. В {link:third-war}Третью войну{/link}, когда волшебники его ордена умирали и восставали вновь на стороне {link:scourge}Плети{/link}, он призвал {red:worgen}воргенов{/red} сражаться за них. Воргены перебили мертвых, а затем обратились против живых. Доведенный виной до безумия, Аругал принял зверей как своих сыновей, захватил крепость барона {link:baron-silverlaine}Сильверлейн{/link}а и назвал ее Крепостью Темного Клыка. {link:ott}Отт{/link}уда его проклятие расползлось по {link:silverpine-forest}Серебряному бору{/link}.]=],
		},
		{
			title = "Значение",
			text = [=[Аругал — корень воргенской заразы в Серебряном бору. Его оковы сковывают жителей Деревни П{link:ogres}огр{/link}ебальных Костров, его магия осквернила рудокопов Серебряного рудника, а его сыновья охотятся на дорогах. Для {link:forsaken}Отрекшихся{/link} он — последнее большое препятствие на пути к власти над лесом.]=],
		},
		{
			title = "Деяния",
			text = [=[• Сперва он жил на пшеничной ферме на севере Серебряного бора и оставил там свои книги заклинаний.
• Он призвал воргенов против воли собратьев.
• Он проклял Деревню П{link:ogres}огр{/link}ебальных Костров и правит ею через ее совет.
• Он захватил крепость барона и сделал ее мертвецов своими домочадцами.
• Он держит огромного зверя по кличке {link:fenrus-the-devourer}Фенрус{/link} и слуг тени из-за пределов мира.
• В бою он проклятием обращает врагов в воргенов и обрушивает на них стрелы Бездны и гром.]=],
		},
		{
			title = "Неизвестное",
			text = [=[Ни одна летопись этих дней не рассказывает о жизни архимага до Третьей войны и о том, откуда на самом деле пришли его воргены.]=],
		},
	},
	chapters = {
		{
			title = "Лекарство",
			hint = "Добудьте заклинание архимага на ферме, где он некогда жил.",
			text = [=[Среди книг, которые Аругал оставил на ферме, было заклинание, которое он называл своим лекарством. {link:dalar-dawnweaver}Далар Ткач Рассвета{/link}, знавший орден {link:kirin-tor}Кирин-Тор{/link} изнутри, прочел его с презрением. Он вслух дивился, как такого человека вообще приняли в орден. Заклинания этого архимага, сказал он, так слабы, что любой ученик увидит их насквозь.]=],
		},
		{
			title = "Оковы Деревни Погребальных Костров",
			hint = [=[Принесите оковы из Деревни Погребальных Костров мертвому архимагу в Гробнице.]=],
			text = [=[Слабость своей магии Аругал восполнял зачарованными вещами. Каждый ворген из стаи Лунной Ярости носил его оковы, как и каждый житель Деревни П{link:ogres}огр{/link}ебальных Костров — человек днем и зверь ночью. Из этих оков {link:dalar-dawnweaver}Далар{/link} извлек силу, которая была ему нужна, чтобы понять проклятие.]=],
		},
		{
			title = "Обман",
			hint = [=[Помогите мертвому архимагу доказать его утверждение останками со Стены Седогрива.]=],
			text = [=[Со временем {link:dalar-dawnweaver}Далар{/link} пришел к выводу, которого никто не ждал. Оковы доказывали, что Аругал мог сковать воргенов. Они не доказывали, что он их создал. Его знаменитое проклятие было слишком немощным, чтобы держаться долго. Воргены, сказал Далар, распространяют свое проклятие каким-то иным путем.]=],
		},
		{
			title = "Смерть архимага",
			hint = [=[Поднимитесь на вершину Крепости Темного Клыка и положите конец чарам архимага.]=],
			text = [=[{link:dalar-dawnweaver}Далар{/link} не желал, чтобы {link:sylvanas-windrunner}Темная Госпожа{/link} заявила права на {link:silverpine-forest}Серебряный бор{/link}, пока Аругал жив, и послал за головой архимага. На вершине своей крепости, среди своих слуг и сыновей, Аругал был убит. Его голову отнесли в Гробницу.]=],
		},
	},
	mentions = {
		{ text = "«Безрассудство архимага», лекарство" },
		{ text = "«Безрассудство архимага», оковы" },
		{ text = "«Безрассудство архимага», новый вывод" },
		{ text = "«Остановить заразу»" },
		{ text = "«Засада в Деревне П{link:ogres}огр{/link}ебальных Костров»" },
		{ text = "«Аругал должен умереть»" },
	},
	bonds = {
		{ id = "dalar-dawnweaver", name = "Далар Ткач Рассвета", note = "презирает его" },
		{ id = "baron-silverlaine", name = "барон Сильверлейн", note = "обитает призраком в его крепости" },
		{ id = "fenrus-the-devourer", name = "Фенрус Пожиратель", note = "его огромный питомец" },
		{ id = "pyrewood-villagers", name = "Жители Деревни Погребальных Костров", note = "прокляты им" },
		{ id = "apothecary-berard", name = "аптекарь Берард", note = "лишился рассудка из-за проклятия" },
	},
})

Translate("ruRU", "baron-silverlaine", {
	title = "Барон Сильверлейн",
	subtitle = "Мстительный призрак",
	found = "Трапезная Крепости Темного Клыка",
	hint = "Ищите призрак прежнего хозяина крепости в ее трапезной.",
	allegiance = "Дом Сильверлейнов",
	aliases = { "Сильверлейн" },
	sections = {
		{
			title = "Обзор",
			text = [=[Барон Сильверлейн был благородным хозяином крепости, что стоит над Деревней П{link:ogres}огр{/link}ебальных Костров. Когда пришли воргены архимага, они осадили его дом, и тот пал. Сильверлейн погиб вместе с ним. Покоя он не обрел. Его призрак ходит по трапезной, где он некогда пировал, среди мертвых слуг своего дома, и обращает свой гнев на всякого, кто туда вторгается.]=],
		},
		{
			title = "Значение",
			text = [=[Сильверлейн — первая жертва безрассудства архимага в стенах крепости и ее законный хозяин. Крепость принадлежала ему прежде, чем стала Темным Клыком. Она быстро пала во тьму и запустение, и воргены, которые ее взяли, теперь рыщут по комнатам вокруг его зала. Его мстительный дух напоминает, что архимаг построил свое убежище на чужих могилах.]=],
		},
		{
			title = "Деяния",
			text = [=[• Его крепость осадили воргены, и она пала.
• Его домочадцы погибли вместе с ним, и мертвецы его дома все еще служат в залах.
• В смерти он набрасывает на врагов пелену тьмы, которая ослабляет всякое исцеляющее прикосновение.
• Он до сих пор носит печать своей семьи.]=],
		},
		{
			title = "Неизвестное",
			text = [=[Ни одна летопись этих дней не называет ни личного имени барона, ни его рода, ни господина, которому он служил. Не написано и о том, почему его призрак остается, когда столь многие другие ушли.]=],
		},
	},
	chapters = {
		{
			title = "Хозяин трапезной",
			hint = "Сразитесь с призраком барона в его собственном зале.",
			text = [=[Мертвецы дома все еще привязаны к крепости. Слуги и стражники стенают в ее залах, а барон ходит среди них в своей трапезной. Он не сумел уберечь свой дом от воргенов. С тех пор он не простил никого, кто в него входит.]=],
		},
	},
	mentions = {
		{ text = "«{link:archmage-arugal}Аругал{/link} должен умереть»" },
	},
	bonds = {
		{ id = "archmage-arugal", name = "архимаг Аругал", note = "захватил его крепость" },
		{ id = "commander-springvale", name = "командир Спрингвейл", note = "командует его мертвыми солдатами" },
	},
})

Translate("ruRU", "commander-springvale", {
	title = "Командир Спрингвейл",
	subtitle = "Командир мертвой стражи",
	found = "Зал совета в Крепости Темного Клыка",
