			title = "Обзор",
			text = [=[Командир Спрингвейл возглавлял солдат барона {link:baron-silverlaine}Сильверлейн{/link}а. Когда воргены штурмовали крепость, он пал на своем посту и восстал вновь одним из ее мертвецов. Он все еще держит зал совета со своими измученными офицерами, а призраки его стражников стенают в залах вокруг.]=],
		},
		{
			title = "Значение",
			text = [=[При жизни Спрингвейл был служителем {link:holy-light}Света{/link}, и Свет не до конца покинул его. Он по-прежнему исцеляет им свои раны, {link:ogres}огр{/link}аждает себя им и сражает врагов молотом правосудия. Это горькое зрелище: защитник крепости, которого смерть превратила в еще одного стража логова архимага. В этой участи он не одинок. Рядом с ним стоят измученные офицеры, по залам ходят стенающие стражники, а неупокоенные слуги все еще прибирают комнаты хозяина, которого больше нет.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он командовал солдатами барона.
• Он погиб при падении крепости.
• Он все еще несет стражу вместе со своими офицерами над комнатами, которые больше не принадлежат его господину.]=],
		},
		{
			title = "Неизвестное",
			text = [=[Ни одна летопись этих дней не говорит, какое имя Спрингвейл носил до крепости и где он научился владеть {link:holy-light}Свет{/link}ом.]=],
		},
	},
	chapters = {
		{
			title = "Последняя стража",
			hint = "Сразитесь с мертвым командиром и его офицерами.",
			text = [=[Крепость пала, и его господин мертв. Спрингвейл все равно держит свой пост, и офицеры стоят рядом с ним. Когда входят чужаки, он призывает против них {link:holy-light}Свет{/link}, как призывал против воргенов.]=],
		},
	},
	mentions = {
		{ text = "«{link:archmage-arugal}Аругал{/link} должен умереть»" },
	},
	bonds = {
		{ id = "baron-silverlaine", name = "барон Сильверлейн", note = "его господин" },
		{ id = "archmage-arugal", name = "архимаг Аругал", note = "хозяин крепости, за которую он погиб" },
	},
})

